import pandas as pd,numpy as np
from scipy.optimize import least_squares
files=['train/A_vref_op1.csv','train/A_amb_op1.csv','train/A_gentrip_op1.csv','train/A_fault_op1.csv','train/A_vref_op3.csv','train/A_load_op2.csv','train/A_amb_op2.csv','train/A_line_op3.csv']
D=[]
for f in files:
    d=pd.read_csv(f).iloc[::5]
    D.append((f,d.time_s.values,d.voltage_pu.values,d.bus_angle_rad.values,d.voltage_setpoint_pu.values,d.active_power_pu.values,d.reactive_power_pu.values))
dt=0.005
def simQ(p,V,Vs,Q0,V0):
    Kp,Ki,Tf=p
    x=0.0;Vf=V[0];n=len(V);Q=np.empty(n)
    for k in range(n):
        Q[k]=Q0+Kp*(Vs[k]-Vf)+x
        x+=dt*Ki*(Vs[k]-Vf)
        Vf+=dt*(V[k]-Vf)/Tf
    return Q
def res(p):
    return np.concatenate([(simQ(p,V,Vs,Q[0],V[0])-Q)/0.001 for f,t,V,th,Vs,P,Q in D])
for p0 in [[1,1,0.05],[2,5,0.2]]:
    r=least_squares(res,p0,bounds=([-20,-200,0.002],[20,200,5]),x_scale='jac',max_nfev=40)
    print(np.round(r.x,4),np.sqrt(np.mean(r.fun**2)))
    for f,t,V,th,Vs,P,Q in D:
        print(f,np.std(simQ(r.x,V,Vs,Q[0],V[0])-Q).round(4))
